css:
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  background: #0b1030;
  color: #f2f4ff;
  font-family: system-ui, Arial, sans-serif;
}
.app {
  max-width: 520px;
  margin: 0 auto;
  padding: 12px;
  text-align: center;
}
h1 { margin: 4px 0 8px; font-size: 1.6rem; color: #ffd84d; }
.info { font-size: 0.9rem; line-height: 1.35; }
.info p { margin: 4px 0; }
.hud {
  display: flex;
  justify-content: space-around;
  margin: 8px 0;
  font-size: 1.1rem;
}
#game-status {
  min-height: 2.6em;
  padding: 6px 10px;
  margin-bottom: 8px;
  border-radius: 8px;
  background: #1a2260;
}
#game-status[data-state="playing"] { background: #1b5e3a; }
#game-status[data-state="won"] { background: #7a5c00; }
#game-status[data-state="lost"] { background: #7a1f2b; }
canvas {
  width: 100%;
  max-width: 480px;
  height: auto;
  background: linear-gradient(#141a55, #0b1030);
  border: 2px solid #3d4aa8;
  border-radius: 10px;
  touch-action: none;
  display: block;
  margin: 0 auto 10px;
}
button {
  font-size: 1.1rem;
  padding: 10px 22px;
  border: 0;
  border-radius: 8px;
  background: #ffd84d;
  color: #222;
  cursor: pointer;
  font-weight: 700;
}
button:hover { background: #ffe680; }
button:focus-visible { outline: 3px solid #fff; }

js:
(function () {
  var canvas = document.getElementById('board');
  var ctx = canvas.getContext('2d');
  var btn = document.getElementById('start-game');
  var status = document.getElementById('game-status');
  var scoreEl = document.getElementById('score');
  var livesEl = document.getElementById('lives');
  var W = canvas.width, H = canvas.height;
  var GOAL = 15;

  var state = 'idle';
  var player, items, score, lives, spawnTimer, keys = {}, lastTime = 0, rafId = null;

  function setStatus(s, text) {
    status.setAttribute('data-state', s);
    status.textContent = text;
  }

  function reset() {
    player = { x: W / 2 - 35, y: H - 30, w: 70, h: 18, speed: 330 };
    items = [];
    score = 0;
    lives = 3;
    spawnTimer = 0;
    scoreEl.textContent = score;
    livesEl.textContent = lives;
  }

  function start() {
    reset();
    state = 'playing';
    setStatus('playing', 'Spelet pågår! Fånga stjärnorna ⭐ och undvik meteoriter ☄️');
    btn.textContent = 'Starta om';
    lastTime = performance.now();
    if (rafId) cancelAnimationFrame(rafId);
    rafId = requestAnimationFrame(loop);
    btn.blur();
  }

  function spawn() {
    var isRock = Math.random() < 0.3;
    items.push({
      x: 20 + Math.random() * (W - 40),
      y: -20,
      r: 14,
      vy: 70 + Math.random() * 50 + score * 3,
      type: isRock ? 'rock' : 'star'
    });
  }

  function end(won) {
    state = won ? 'won' : 'lost';
    setStatus(state, won ? 'Grattis, du vann! Du fångade ' + GOAL + ' stjärnor! Tryck på Starta om för att spela igen.' : 'Slut på liv! Du fångade ' + score + ' stjärnor. Tryck på Starta om för att försöka igen.');
    btn.textContent = 'Spela igen';
  }

  function update(dt) {
    if (keys.ArrowLeft || keys.a) player.x -= player.speed * dt;
    if (keys.ArrowRight || keys.d) player.x += player.speed * dt;
    player.x = Math.max(0, Math.min(W - player.w, player.x));

    spawnTimer -= dt;
    if (spawnTimer <= 0) {
      spawn();
      spawnTimer = 0.7 + Math.random() * 0.5;
    }

    for (var i = items.length - 1; i >= 0; i--) {
      var it = items[i];
      it.y += it.vy * dt;
      var hit = it.y + it.r >= player.y && it.y - it.r <= player.y + player.h &&
                it.x >= player.x - it.r / 2 && it.x <= player.x + player.w + it.r / 2;
      if (hit) {
        items.splice(i, 1);
        if (it.type === 'star') {
          score++;
          scoreEl.textContent = score;
          if (score >= GOAL) { end(true); return; }
        } else {
          lives--;
          livesEl.textContent = lives;
          if (lives <= 0) { end(false); return; }
        }
      } else if (it.y > H + 20) {
        items.splice(i, 1);
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#ffffff';
    for (var s = 0; s < 30; s++) {
      ctx.fillRect((s * 97) % W, (s * 53) % H, 2, 2);
    }
    if (!player) return;
    ctx.fillStyle = '#4dd0ff';
    ctx.fillRect(player.x, player.y, player.w, player.h);
    ctx.fillStyle = '#1a8fb8';
    ctx.fillRect(player.x, player.y, player.w, 5);
    ctx.font = '26px serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      ctx.fillText(it.type === 'star' ? '⭐' : '☄️', it.x, it.y);
    }
  }

  function loop(t) {
    var dt = Math.min(0.05, (t - lastTime) / 1000);
    lastTime = t;
    if (state === 'playing') update(dt);
    draw();
    if (state === 'playing') rafId = requestAnimationFrame(loop);
  }

  function pointerMove(e) {
    if (state !== 'playing') return;
    var rect = canvas.getBoundingClientRect();
    var x = (e.clientX - rect.left) * (W / rect.width);
    player.x = Math.max(0, Math.min(W - player.w, x - player.w / 2));
  }

  canvas.addEventListener('pointermove', pointerMove);
  canvas.addEventListener('pointerdown', pointerMove);

  window.addEventListener('keydown', function (e) {
    var k = e.key.length === 1 ? e.key.toLowerCase() : e.key;
    if (k === 'ArrowLeft' || k === 'ArrowRight' || k === 'a' || k === 'd') {
      keys[k] = true;
      e.preventDefault();
    }
  });
  window.addEventListener('keyup', function (e) {
    var k = e.key.length === 1 ? e.key.toLowerCase() : e.key;
    keys[k] = false;
  });

  btn.addEventListener('click', start);

  reset();
  draw();
})();
